import{_ as t,o as s,c as i,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/QUICK-CLUSTER.md","filePath":"manual-en/QUICK-CLUSTER.md","lastUpdated":1785684581000}'),n={name:"manual-en/QUICK-CLUSTER.md"};function o(c,e,r,l,d,h){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h3 id="_15-15-quick-cluster" tabindex="-1">15.15 QUICK CLUSTER <a class="header-anchor" href="#_15-15-quick-cluster" aria-label="Permalink to &quot;15.15 QUICK CLUSTER&quot;">​</a></h3><pre><code>QUICK CLUSTER var_list
      [/CRITERIA=CLUSTERS(k) [MXITER(max_iter)] CONVERGE(epsilon) [NOINITIAL]]
      [/MISSING={EXCLUDE,INCLUDE} {LISTWISE, PAIRWISE}]
      [/PRINT={INITIAL} {CLUSTER}]
      [/SAVE[=[CLUSTER[(membership_var)]] [DISTANCE[(distance_var)]]]
</code></pre><p>The <code>QUICK CLUSTER</code> command performs k-means clustering on the dataset. This is useful when you wish to allocate cases into clusters of similar values and you already know the number of clusters.</p><p>The minimum specification is ‘QUICK CLUSTER’ followed by the names of the variables which contain the cluster data. Normally you will also want to specify <code>/CRITERIA=CLUSTERS(k)</code> where k is the number of clusters. If this is not specified, then k defaults to 2.</p><p>If you use <code>/CRITERIA=NOINITIAL</code> then a naive algorithm to select the initial clusters is used. This will provide for faster execution but less well separated initial clusters and hence possibly an inferior final result.</p><p><code>QUICK CLUSTER</code> uses an iterative algorithm to select the clusters centers. The subcommand <code>/CRITERIA=MXITER(max_iter)</code> sets the maximum number of iterations. During classification, PSPP will continue iterating until until max_iter iterations have been done or the convergence criterion (see below) is fulfilled. The default value of max_iter is 2.</p><p>If however, you specify <code>/CRITERIA=NOUPDATE</code> then after selecting the initial centers, no further update to the cluster centers is done. In this case, max_iter, if specified. is ignored.</p><p>The subcommand <code>/CRITERIA=CONVERGE(epsilon)</code> is used to set the convergence criterion. The value of convergence criterion is epsilon times the minimum distance between the <em>initial</em> cluster centers. Iteration stops when the mean cluster distance between one iteration and the next is less than the convergence criterion. The default value of epsilon is zero.</p><p>The <code>MISSING</code> subcommand determines the handling of missing variables. If <code>INCLUDE</code> is set, then user-missing values are considered at their face value and not as missing values. If <code>EXCLUDE</code> is set, which is the default, user-missing values are excluded as well as system-missing values.</p><p>If <code>LISTWISE</code> is set, then the entire case is excluded from the analysis whenever any of the clustering variables contains a missing value. If <code>PAIRWISE</code> is set, then a case is considered missing only if all the clustering variables contain missing values. Otherwise it is clustered on the basis of the non-missing values. The default is <code>LISTWISE</code>.</p><p>The <code>PRINT</code> subcommand requests additional output to be printed. If <code>INITIAL</code> is set, then the initial cluster memberships will be printed. If <code>CLUSTER</code> is set, the cluster memberships of the individual cases are displayed (potentially generating lengthy output).</p><p>You can specify the subcommand <code>SAVE</code> to ask that each case’s cluster membership and the euclidean distance between the case and its cluster center be saved to a new variable in the active dataset. To save the cluster membership use the <code>CLUSTER</code> keyword and to save the distance use the <code>DISTANCE</code> keyword. Each keyword may optionally be followed by a variable name in parentheses to specify the new variable which is to contain the saved parameter. If no variable name is specified, then PSPP will create one.</p>`,12)])])}const I=t(n,[["render",o]]);export{m as __pageData,I as default};
